        {% set ns.basic = row.amount or 0 %}
    {% elif "medical" in component %}
        {% set ns.medical = row.amount or 0 %}
    {% elif "other allowance" in component or "other" in component %}
        {% set ns.other = row.amount or 0 %}
    {% endif %}
{% endfor %}
{% set total_salary = ns.basic + ns.medical + ns.other %}

<style>
