    margin-top: 4px;
    font-size: 7.8px;
    font-weight: bold;
    text-align: right;
}

.jtq-sign-manager {
    width: 140px;
    margin-top: 18px;
    margin-left: 25px;
    text-align: center;
    direction: rtl;
    font-size: 8px;
    font-weight: bold;
}

.jtq-sign-line {
    border-top: 1px solid #000;
    height: 5px;
    margin-bottom: 3px;
}

.jtq-instructions-wrap {
