    margin-bottom: 3px;
}

.jtq-instructions {
    direction: rtl;
    text-align: right;
    font-size: 7.2px;
    line-height: 1.35;
    font-weight: bold;
}

.jtq-instructions div {
    margin-bottom: 2px;
}

