</style>

<div class="jtq-letter">

    <div class="jtq-title">آزمائشی تقرر نامه برائے معلم / معلمه</div>

    <table class="jtq-info-table">
        <tr>
            <td class="jtq-label">فائل نمبر</td>
            <td class="jtq-value">{{ doc.get("custom_file_no") or employee_id }}</td>
            <td class="jtq-label">کوڈ نمبر</td>
            <td class="jtq-value">{{ doc.get("custom_code_no") or employee_id }}</td>
            <td class="jtq-label">تاریخ</td>
