            <td class="jtq-label">ولدیت</td>
            <td class="jtq-value">{{ father_name }}</td>
            <td class="jtq-label">شناختی کارڈ نمبر</td>
            <td class="jtq-value">{{ cnic }}</td>
        </tr>
        <tr>
            <td class="jtq-label">موجوده پته</td>
