            <td class="jtq-value">{{ permanent_address }}</td>
        </tr>
        <tr>
            <td class="jtq-label">رابطه نمبر</td>
            <td class="jtq-value">{{ phone }}</td>
            <td class="jtq-label">اکاؤنٹ نمبر</td>
            <td class="jtq-value">{{ doc.get("bank_ac_no") or "-" }}</td>
            <td class="jtq-label">بینک کا نام</td>
            <td class="jtq-value">{{ doc.get("bank_name") or "-" }}</td>
        </tr>
        <tr>
            <td class="jtq-label">دینی تعلیم</td>
