            <td class="jtq-label">عصری تعلیم</td>
            <td class="jtq-value">{{ doc.get("custom_education") or "-" }}</td>
            <td class="jtq-label">مقام تقرر</td>
            <td class="jtq-value">{{ shift_location }}</td>
        </tr>
        <tr>
            <td class="jtq-label">تاریخ تقرر</td>
            <td class="jtq-value">{{ frappe.utils.formatdate(appointment_date, "dd/MM/yyyy") }}</td>
            <td class="jtq-label">مطابق</td>
            <td class="jtq-value">{{ doc.get("custom_hijri_date") or "-" }}</td>
            <td class="jtq-label">شاخ / حلقه</td>
            <td class="jtq-value">{{ branch }}</td>
