{% set emp = frappe.get_doc("Employee", doc.employee) if doc.employee else None %}
{% set currency = doc.currency or frappe.db.get_value("Company", doc.company, "default_currency") or "PKR" %}

{% set department = emp.department if emp else "-" %}
{% set designation = emp.designation if emp else "-" %}
{% set madrasa = emp.get("custom_madrasa") or emp.get("madrasa") or "-" if emp else "-" %}
{% set branch_id = emp.branch if emp else "" %}
{% set branch_name = frappe.db.get_value("Branch", branch_id, "branch") or frappe.db.get_value("Branch", branch_id, "branch_name") or branch_id or "-" %}

<style>
.print-heading,
.print-format h1:first-child,
.print-format .page-break > h1:first-child {
    display: none !important;
}

.print-format {
    padding: 0 !important;
    margin: 0 !important;
}

.ss-page {
    font-family: Arial, Helvetica, sans-serif;
    color: #000;
    width: 100%;
    max-width: 185mm;
    margin: 0 auto;
    padding: 20mm 5mm 0 5mm;
    font-size: 10px;
    line-height: 1.05;
}

.ss-title {
    text-align: right;
    font-size: 11px;
    margin-bottom: 5px;
}

.ss-top-line {
    border-top: 2px solid #000;
    margin-bottom: 18mm;
}

.ss-info-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-bottom: 10mm;
}

.ss-info-table td {
    padding: 1px 4px 3px 4px;
    line-height: 1.05;
    vertical-align: top;
}

.ss-label {
    font-weight: bold;
    width: 16%;
    white-space: nowrap;
}

.ss-value {
    width: 34%;
    white-space: nowrap;
}

.ss-label-right {
    font-weight: bold;
    width: 18%;
    white-space: nowrap;
}

.ss-value-right {
    width: 32%;
    text-align: right;
    white-space: nowrap;
}

.ss-grid-wrap {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-bottom: 8mm;
}

.ss-grid-wrap > tbody > tr > td {
    width: 50%;
    vertical-align: top;
    padding: 0;
}

.ss-grid-wrap .left-box {
    padding-right: 17mm;
}

.ss-grid-wrap .right-box {
    padding-left: 17mm;
}

.ss-component-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    font-size: 9px;
}

.ss-component-table th,
.ss-component-table td {
    border: 1px solid #000;
    padding: 2px 4px;
    line-height: 1.05;
}

.ss-component-table th {
    background: #eeeeee;
    color: #000;
    font-weight: bold;
    text-align: left;
}

.ss-sr {
    width: 9%;
    text-align: center;
}

.ss-component {
    width: 66%;
}

.ss-amount {
    width: 25%;
    text-align: right;
    white-space: nowrap;
}

.ss-summary {
    width: 48%;
    margin-left: auto;
    margin-bottom: 8mm;
    border-collapse: collapse;
    table-layout: fixed;
    font-size: 11px;
    line-height: 1.05;
}

.ss-summary td {
    padding: 1px 0 3px 0;
    line-height: 1.05;
}

.ss-summary-label {
    width: 45%;
    text-align: left;
}

.ss-summary-amount {
    width: 55%;
    text-align: right;
    white-space: nowrap;
}

.ss-rounded {
    font-weight: bold;
    font-size: 13px;
}

.ss-words-label {
    vertical-align: top;
}

.ss-words {
    text-align: right;
    line-height: 1.25;
}

.ss-leave-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    font-size: 10px;
    margin-top: 0;
}

.ss-leave-table th,
.ss-leave-table td {
    border: 1px solid #000;
    padding: 3px 5px;
    line-height: 1.05;
}

.ss-leave-table th {
    background: #eeeeee;
    color: #000;
    font-weight: bold;
    text-align: left;
}

.text-right {
    text-align: right;
}

.text-center {
    text-align: center;
}
</style>

<div class="ss-page">

    <div class="ss-title">
        Sal Slip/{{ doc.employee or "-" }}/{{ doc.name or "-" }}
    </div>

    <div class="ss-top-line"></div>

    <table class="ss-info-table">
        <tr>
            <td class="ss-label">Company</td>
            <td class="ss-value">{{ doc.company or "-" }}</td>

            <td class="ss-label-right">Start Date</td>
            <td class="ss-value-right">{{ frappe.utils.formatdate(doc.start_date, "dd-MM-yyyy") if doc.start_date else "-" }}</td>
        </tr>

        <tr>
            <td class="ss-label">Employee</td>
            <td class="ss-value">{{ doc.employee or "-" }}</td>

            <td class="ss-label-right">End Date</td>
            <td class="ss-value-right">{{ frappe.utils.formatdate(doc.end_date, "dd-MM-yyyy") if doc.end_date else "-" }}</td>
        </tr>

        <tr>
            <td class="ss-label">Employee Name</td>
            <td class="ss-value">{{ doc.employee_name or "-" }}</td>

            <td class="ss-label-right">Working Days</td>
            <td class="ss-value-right">{{ doc.total_working_days or 0 }}</td>
        </tr>

        <tr>
            <td class="ss-label">Department</td>
            <td class="ss-value">{{ department or "-" }}</td>

            <td class="ss-label-right">Absent</td>
            <td class="ss-value-right">{{ doc.absent_days or 0 }}</td>
        </tr>

        <tr>
            <td class="ss-label">Designation</td>
            <td class="ss-value">{{ designation or "-" }}</td>

            <td class="ss-label-right">Leaves</td>
            <td class="ss-value-right">{{ doc.leave_days or 0 }}</td>
        </tr>

        <tr>
            <td class="ss-label">Madrasa</td>
            <td class="ss-value">{{ madrasa or "-" }}</td>

            <td class="ss-label-right">Leaves Without Pay</td>
            <td class="ss-value-right">{{ doc.leave_without_pay or 0 }}</td>
        </tr>

        <tr>
            <td class="ss-label">Branches Name</td>
            <td class="ss-value">{{ branch_name or "-" }}</td>

            <td class="ss-label-right">Deduction Hour</td>
            <td class="ss-value-right">{{ doc.get("custom_deduction_hour") or 0 }}</td>
        </tr>

        <tr>
            <td class="ss-label">Month</td>
            <td class="ss-value">{{ frappe.utils.formatdate(doc.start_date, "MMMM") if doc.start_date else "-" }}</td>

            <td class="ss-label-right">Payment Days</td>
            <td class="ss-value-right">{{ doc.payment_days or 0 }}</td>
        </tr>

        <tr>
            <td class="ss-label"></td>
            <td class="ss-value"></td>

            <td class="ss-label-right">Mode Of Payment</td>
            <td class="ss-value-right">{{ doc.mode_of_payment or emp.get("salary_mode") or "-" if emp else doc.mode_of_payment or "-" }}</td>
        </tr>
    </table>

    <table class="ss-grid-wrap">
        <tr>
            <td class="left-box">
                <table class="ss-component-table">
                    <thead>
                        <tr>
                            <th class="ss-sr">Sr</th>
                            <th class="ss-component">Component</th>
                            <th class="ss-amount">Amount</th>
                        </tr>
                    </thead>
                    <tbody>
                        {% for row in doc.earnings %}
                        <tr>
                            <td class="ss-sr">{{ loop.index }}</td>
                            <td>{{ row.salary_component or "-" }}</td>
                            <td class="ss-amount">{{ frappe.utils.fmt_money(row.amount or 0, currency=currency) }}</td>
                        </tr>
                        {% endfor %}
                    </tbody>
                </table>
            </td>

            <td class="right-box">
                <table class="ss-component-table">
                    <thead>
                        <tr>
                            <th class="ss-sr">Sr</th>
                            <th class="ss-component">Component</th>
                            <th class="ss-amount">Amount</th>
                        </tr>
                    </thead>
                    <tbody>
                        {% for row in doc.deductions %}
                        <tr>
                            <td class="ss-sr">{{ loop.index }}</td>
                            <td>{{ row.salary_component or "-" }}</td>
                            <td class="ss-amount">{{ frappe.utils.fmt_money(row.amount or 0, currency=currency) }}</td>
                        </tr>
                        {% endfor %}
                    </tbody>
                </table>
            </td>
        </tr>
    </table>

    <table class="ss-summary">
        <tr>
            <td class="ss-summary-label">Gross Pay:</td>
            <td class="ss-summary-amount">{{ frappe.utils.fmt_money(doc.gross_pay or 0, currency=currency) }}</td>
        </tr>
        <tr>
            <td class="ss-summary-label">Total Deduction:</td>
            <td class="ss-summary-amount">{{ frappe.utils.fmt_money(doc.total_deduction or 0, currency=currency) }}</td>
        </tr>
        <tr>
            <td class="ss-summary-label">Net Pay:</td>
            <td class="ss-summary-amount">{{ frappe.utils.fmt_money(doc.net_pay or 0, currency=currency) }}</td>
        </tr>
        <tr>
            <td class="ss-summary-label">Rounded Total:</td>
            <td class="ss-summary-amount ss-rounded">{{ frappe.utils.fmt_money(doc.rounded_total or doc.net_pay or 0, currency=currency) }}</td>
        </tr>
        <tr>
            <td class="ss-summary-label ss-words-label">Total in Words:</td>
            <td class="ss-words">{{ frappe.utils.money_in_words(doc.rounded_total or doc.net_pay or 0, currency) }}</td>
        </tr>
    </table>

    <table class="ss-leave-table">
        <thead>
            <tr>
                <th style="width: 5%;">Sr</th>
                <th>Leave Type</th>
                <th class="text-right" style="width: 22%;">Total Allocated Leaves</th>
                <th class="text-right" style="width: 16%;">Used Leaves</th>
                <th class="text-right" style="width: 18%;">Available Leaves</th>
            </tr>
        </thead>
        <tbody>
            {% if doc.get("leave_details") %}
                {% for row in doc.get("leave_details") %}
                <tr>
                    <td class="text-center">{{ loop.index }}</td>
                    <td>{{ row.leave_type or "-" }}</td>
                    <td class="text-right">{{ row.total_allocated_leaves or row.get("total_leaves_allocated") or 0 }}</td>
                    <td class="text-right">{{ row.used_leaves or 0 }}</td>
                    <td class="text-right">{{ row.available_leaves or 0 }}</td>
                </tr>
                {% endfor %}
            {% else %}
                <tr>
                    <td colspan="5" class="text-center">No Leave Allocation Found</td>
                </tr>
            {% endif %}
        </tbody>
    </table>

</div>
